    payloadInput.type = 'hidden';
    payloadInput.name = 'payload';
    payloadInput.value = JSON.stringify(data);
    
    form.appendChild(urlInput);
    form.appendChild(payloadInput);
    document.body.appendChild(form);
    form.submit();
    
    setTimeout(() => btn.remove(), 3000);
